import{_ as o,r as n,o as e,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Индикаторы загрузки - October CMS - 3.x","titleTemplate":false,"description":"Индикация загрузки страницы.","frontmatter":{"subtitle":"Индикация загрузки страницы."},"headers":[{"level":2,"title":"Индикатор прогресса","slug":"индикатор-прогресса","link":"#индикатор-прогресса","children":[]},{"level":2,"title":"Кнопка загрузки","slug":"кнопка-загрузки","link":"#кнопка-загрузки","children":[]},{"level":2,"title":"Переключение видимости элементов","slug":"переключение-видимости-элементов","link":"#переключение-видимости-элементов","children":[{"level":3,"title":"Обнаружение глобальных запросов","slug":"обнаружение-глобальных-запросов","link":"#обнаружение-глобальных-запросов","children":[]},{"level":3,"title":"Нацеливание на конкретные обработчики","slug":"нацеливание-на-конкретные-обработчики","link":"#нацеливание-на-конкретные-обработчики","children":[]}]},{"level":2,"title":"Работа с JavaScript","slug":"работа-с-javascript","link":"#работа-с-javascript","children":[]}],"relativePath":"3.x/ru/cms/features/loaders.md","filePath":"3.x/ru/cms/features/loaders.md"}'),i={name:"3.x/ru/cms/features/loaders.md"};function k(r,a,d,g,m,h){const t=n("pre-heading"),p=n("post-heading");return e(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Индикаторы загрузки",-1)),s(p),a[1]||(a[1]=u(`<p>Когда AJAX-фреймворк отправляет запрос на сервер, рекомендуется отображать индикатор загрузки, поскольку страница может обновиться не сразу. Существует несколько подходов и стандартных индикаторов загрузки, чтобы обозначить, что AJAX-запрос был отправлен и выполняется.</p><h2 id="индикатор-прогресса"><a href="#индикатор-прогресса" class="header-anchor">#</a> Индикатор прогресса</h2><p>Заметная функция AJAX-фреймворка — индикатор прогресса, отображаемый в верхней части страницы при выполнении AJAX-запроса. Индикатор прогресса отслеживает AJAX-запросы и появляется, когда запрос длится более 300 мс, и скрывается после завершения запроса.</p><p>Чтобы отключить индикатор прогресса для запроса, установите атрибут <code>data-request-progress-bar</code> в значение <code>false</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-progress-bar</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Do something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>В JavaScript установите параметр <code>progressBar</code> AJAX-запроса в <code>false</code>.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token string">&#39;onSilentRequest&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">progressBar</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы отключить индикатор прогресса глобально, установите свойство <code>visibility</code> в значение <code>hidden</code> с помощью стилей.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.oc-progress-bar</span> <span class="token punctuation">{</span>
    <span class="token property">visibility</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете отображать индикатор прогресса с помощью JavaScript, используя объект <code>oc.progressBar</code> и функции <code>show</code> / <code>hide</code>.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="кнопка-загрузки"><a href="#кнопка-загрузки" class="header-anchor">#</a> Кнопка загрузки</h2><p>При отправке форм пользователи могут случайно нажать кнопку дважды и вызвать двойную отправку, и это решается с помощью кнопки загрузки. Во время AJAX-запросов элементы button с атрибутом <code>data-attach-loading</code> будут отключены, и к ним будет добавлен CSS-класс <code>oc-attach-loader</code>. Этот класс создаёт спиннер загрузки на элементах button и anchor с помощью CSS-селектора <code>:after</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>#<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
    Do Something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Когда кнопка находится внутри формы с атрибутом <code>oc-attach-loader</code>, индикатор загрузки будет отображаться.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Поскольку элементы input не поддерживают CSS-селектор <code>:after</code>, после них вставляется новый элемент. Элемент удаляется после завершения AJAX-запроса. Это полезно при работе с атрибутом <code>data-track-input</code>, который отслеживает изменения в поле ввода и отправляет AJAX-запрос.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCheckUsername<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-track-input</span>
    <span class="token attr-name">data-attach-loading</span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Вы можете вручную добавить загрузчик на кнопку с помощью объекта <code>oc.attachLoader</code> и функций <code>show</code> / <code>hide</code>, передавая CSS-селектор элемента или объект в качестве первого аргумента.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="переключение-видимости-элементов"><a href="#переключение-видимости-элементов" class="header-anchor">#</a> Переключение видимости элементов</h2><p>Вы можете использовать атрибут <code>data-request-loading</code> для отображения элемента во время AJAX-запроса. Значение — CSS-селектор, который управляет видимостью элемента с помощью свойств display <code>block</code> и <code>none</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-loading</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>.is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Pay Now
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none</span><span class="token punctuation">&quot;</span></span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Processing Payment...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="обнаружение-глобальных-запросов"><a href="#обнаружение-глобальных-запросов" class="header-anchor">#</a> Обнаружение глобальных запросов</h3><p>Вы можете определить, выполняется ли глобальный AJAX-запрос, проверив атрибут <code>data-ajax-progress</code> на HTML-элементе. В стилях это выглядит так:</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">html[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* Display loading indicators */</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Атрибут также добавляется к элементам формы.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">form[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* The form is loading */</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="нацеливание-на-конкретные-обработчики"><a href="#нацеливание-на-конкретные-обработчики" class="header-anchor">#</a> Нацеливание на конкретные обработчики</h3><p>В некоторых случаях вам может потребоваться показать индикатор загрузки для конкретного <a href="./../ajax/handlers.html">обработчика AJAX-событий</a>. Атрибут <code>data-ajax-progress</code> будет содержать имя последнего обработчика, и это можно использовать для нацеливания на конкретный запрос.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Pay Now<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCancel<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-payment-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Processing Payment...
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Это можно нацелить с помощью селектора атрибута в стилях.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> none<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token selector">form[data-ajax-progress=onPay] .is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="работа-с-javascript"><a href="#работа-с-javascript" class="header-anchor">#</a> Работа с JavaScript</h2><p>Для более сложных сценариев вы можете использовать <a href="./../ajax/javascript-api.html">AJAX JavaScript API</a> через события <code>ajax:promise</code> и <code>ajax:always</code>. Эти события можно привязать к документу, форме или целевым элементам.</p><div class="language-js extra-class"><pre class="language-js"><code>formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A new request has started</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A request has ended</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Следующий пример отключит все поля ввода внутри формы во время выполнения запроса.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,38))])}const q=o(i,[["render",k]]);export{f as __pageData,q as default};
